CREATE TABLE IF NOT EXISTS stores(id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL,city VARCHAR(80) NOT NULL,active BOOLEAN NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS users(id INT PRIMARY KEY AUTO_INCREMENT,email VARCHAR(190) NOT NULL UNIQUE,name VARCHAR(80) NOT NULL,password VARCHAR(255) NOT NULL,role ENUM('sales','manager','admin') NOT NULL DEFAULT 'sales',store_id INT NOT NULL,active BOOLEAN NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(store_id) REFERENCES stores(id));
CREATE TABLE IF NOT EXISTS sessions(token CHAR(64) PRIMARY KEY,user_id INT NOT NULL,expires_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS rules(id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,description TEXT,keywords VARCHAR(500) NOT NULL,active BOOLEAN NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS conversations(id INT PRIMARY KEY AUTO_INCREMENT,title VARCHAR(140) NOT NULL,customer VARCHAR(80) NOT NULL,owner_id INT NOT NULL,store_id INT NOT NULL,rule_id INT NOT NULL,transcript MEDIUMTEXT NOT NULL,status ENUM('processing','ready','failed') NOT NULL DEFAULT 'processing',error TEXT,score INT NULL,summary TEXT,audio_path VARCHAR(100),audio_type VARCHAR(80),is_demo BOOLEAN DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,analyzed_at DATETIME NULL,FOREIGN KEY(owner_id) REFERENCES users(id),FOREIGN KEY(store_id) REFERENCES stores(id),FOREIGN KEY(rule_id) REFERENCES rules(id));
CREATE TABLE IF NOT EXISTS findings(id INT PRIMARY KEY AUTO_INCREMENT,conversation_id INT NOT NULL,dimension VARCHAR(100) NOT NULL,verdict TEXT NOT NULL,evidence TEXT NOT NULL,line_index INT NOT NULL DEFAULT 0,confidence INT NOT NULL DEFAULT 65,review ENUM('pending','confirmed','corrected','insufficient') DEFAULT 'pending',note TEXT,reviewer_id INT NULL,reviewed_at DATETIME NULL,FOREIGN KEY(conversation_id) REFERENCES conversations(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS tasks(id INT PRIMARY KEY AUTO_INCREMENT,conversation_id INT NOT NULL,finding_id INT NOT NULL UNIQUE,title VARCHAR(180) NOT NULL,description TEXT NOT NULL,assignee_id INT NOT NULL,creator_id INT NOT NULL,due_date DATE NOT NULL,status ENUM('todo','doing','done') DEFAULT 'todo',completion_note TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,completed_at DATETIME NULL,FOREIGN KEY(conversation_id) REFERENCES conversations(id),FOREIGN KEY(finding_id) REFERENCES findings(id),FOREIGN KEY(assignee_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS audit(id INT PRIMARY KEY AUTO_INCREMENT,user_id INT NULL,action VARCHAR(80) NOT NULL,detail VARCHAR(500) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS login_attempts(email VARCHAR(190) PRIMARY KEY,attempts INT NOT NULL DEFAULT 0,reset_at DATETIME NOT NULL);
